<script setup>
import { reactive, ref, computed, markRaw, onMounted, onBeforeUnmount } from 'vue'
/* 着色器在 src/assets/shaders/ 里（随 bundle 打包）；贴图仍在 public/assets/blockEffect/，
   按 URL 引用，构建时原样拷到 dist/assets。常量与纯函数在同目录的 consts.js。 */
import { VERT_BLOCK, VERT_BLIT, FRAG_BLIT, FRAG_SRC } from '../../assets/shaders/blockEffectShaders.js'
import {
  TEX_DISPLACE_URL, TEX_SPARK_URL, TEX_NOISE_URL,
  BASE_FLOATS, BASE_COLORS, SPARK_TINT,
  SLIDERS, OUTER_SLIDERS, INNER_SLIDERS, TOOLS, TOOL_NAMES, BRUSH_TIPS,
  clamp, medium, noiseIndex, CENTERED, GLOW_W
} from './noisePainter/consts.js'

/* =====================================================================
   噪域画笔（blockArea 画笔）
   着色器与遮罩管线移植自 Phira-Pro 的 blockArea 实现（GPL-3.0，见 README
   「许可与出处」）：ActiveBlock 材质 + EdgeMask / GlowMask / 遮罩置换，
   在浏览器里复刻「enable 之后」的噪域外观，并允许用画笔交互式地绘制区域。
   遮罩网格以原图为基准（官方按屏幕 / 8，这里可调）；片元着色器是上游 GLSL
   原文，只裁掉了本页用不到的悬浮（hover）SDF 与调色板（uColored）分支。
   ===================================================================== */


/* ------------------------------------------------------------------ */
/* 状态                                                                */
/* ------------------------------------------------------------------ */
const S = reactive({
  img: null, imgW: 0, imgH: 0, name: '',
  cell: 12, gw: 0, gh: 0,
  cells: null,             /* 0 空 / 1 普通 / 2 反相 */
  rects: [],               /* {x,y,w,h,subtract} 图像像素 */
  tool: 'brush', subtract: false, brush: 48, square: false,
  time: 6, playing: false,
  edgeStrength: 6,         /* 边缘像素强度 1..6，越大环带越细；6 = 官方 1 格 */
  noiseStrength: 1,        /* 外圈噪声强度 0..4，越大外轮廓被噪声打得越碎越小；1 = 官方 */
  blockPx: 4,              /* 最小像素点大小（原图像素）：遮罩一格 = 这么多像素；本站默认 4，官方 8 */
  rev: 0,                  /* 每次修改 +1，用于失效遮罩缓存 */
  history: [], future: [], sel: null, drag: null, hover: null,
  params: Object.assign({}, BASE_FLOATS),
  zoneCount: 0, perf: '-'
})

const errMsg = ref('')
const dragging = ref(false)
const frameRef = ref(null)
const stageRef = ref(null)
const viewRef = ref(null)
const overlayRef = ref(null)
const fileRef = ref(null)

const toolName = computed(() => TOOL_NAMES[S.tool] || '')

let gl = null, glCanvas = null, overlay = null, octx = null, frameEl = null, stageEl = null
let progBlock = null, progBlit = null
let texDisplace = null, texSpark = null, texNoise = null, texMask = null, texAux = null, texImage = null
let imgDisplace = null, imgSpark = null, imgNoise = null
let noiseR = null, NOISE_W = 0, NOISE_H = 0
let maskKey = '', maskMs = 0, frameMs = 0, lastT = 0, maskEw = 1, maskEh = 1
let dirty = true
const cacheBlock = {}, cacheBlit = {}
let rafId = 0, disposed = false, errTimer = 0

function showErr(msg) {
  errMsg.value = String(msg && msg.stack ? msg.stack : msg)
  clearTimeout(errTimer)
  errTimer = setTimeout(() => { errMsg.value = '' }, 12000)
}

/* ------------------------------------------------------------------ */
/* GL                                                                  */
/* ------------------------------------------------------------------ */
function createGL(canvas) {
  const opts = {
    alpha: false, antialias: false, depth: false, stencil: false,
    preserveDrawingBuffer: true, premultipliedAlpha: false, powerPreference: 'high-performance'
  }
  let g = canvas.getContext('webgl2', opts)
  if (!g) g = canvas.getContext('webgl', opts) || canvas.getContext('experimental-webgl', opts)
  return g
}
function compile(g, type, src) {
  const s = g.createShader(type); g.shaderSource(s, src); g.compileShader(s)
  if (!g.getShaderParameter(s, g.COMPILE_STATUS)) {
    throw new Error('着色器编译失败:\n' + g.getShaderInfoLog(s))
  }
  return s
}
function link(g, vs, fs) {
  const p = g.createProgram(); g.attachShader(p, vs); g.attachShader(p, fs)
  g.bindAttribLocation(p, 0, 'aPos'); g.linkProgram(p)
  if (!g.getProgramParameter(p, g.LINK_STATUS)) throw new Error('着色器链接失败:\n' + g.getProgramInfoLog(p))
  return p
}
function texFromImage(g, img, wrap, filter) {
  const t = g.createTexture()
  g.bindTexture(g.TEXTURE_2D, t)
  g.pixelStorei(g.UNPACK_FLIP_Y_WEBGL, false)
  g.texImage2D(g.TEXTURE_2D, 0, g.RGBA, g.RGBA, g.UNSIGNED_BYTE, img)
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_WRAP_S, wrap)
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_WRAP_T, wrap)
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_MIN_FILTER, filter)
  g.texParameteri(g.TEXTURE_2D, g.TEXTURE_MAG_FILTER, filter)
  return t
}
function makeSolid(r, g_, b, a) {
  const t = gl.createTexture()
  gl.bindTexture(gl.TEXTURE_2D, t)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([r, g_, b, a]))
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  return t
}
function initGL() {
  gl = createGL(glCanvas)
  if (!gl) throw new Error('无法创建 WebGL 上下文，请使用较新的 Chrome / Edge / Firefox。')

  progBlit = link(gl, compile(gl, gl.VERTEX_SHADER, VERT_BLIT), compile(gl, gl.FRAGMENT_SHADER, FRAG_BLIT))
  progBlock = link(gl, compile(gl, gl.VERTEX_SHADER, VERT_BLOCK), compile(gl, gl.FRAGMENT_SHADER, FRAG_SRC))

  const vbo = gl.createBuffer()
  gl.bindBuffer(gl.ARRAY_BUFFER, vbo)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW)
  gl.enableVertexAttribArray(0)
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)

  texDisplace = texFromImage(gl, imgDisplace, gl.MIRRORED_REPEAT, gl.NEAREST) /* 官方 Mirror + Nearest */
  texSpark = texFromImage(gl, imgSpark, gl.REPEAT, gl.NEAREST)                /* 官方 Repeat + Nearest */
  texNoise = texFromImage(gl, imgNoise, gl.MIRRORED_REPEAT, gl.NEAREST)       /* 官方 Mirror + Nearest */

  texAux = makeSolid(0, 0, 0, 0)
  texMask = makeSolid(0, 0, 0, 0)
}
function uB(name) { if (!(name in cacheBlock)) cacheBlock[name] = gl.getUniformLocation(progBlock, name); return cacheBlock[name] }
function uBlit(name) { if (!(name in cacheBlit)) cacheBlit[name] = gl.getUniformLocation(progBlit, name); return cacheBlit[name] }

/* ------------------------------------------------------------------ */
/* 遮罩计算（官方 CPU 等价实现）                                        */
/* ------------------------------------------------------------------ */
/* 单元格是 2 位图层：bit0 = 普通通道，bit1 = 反相通道。
   两个通道各自独立（和官方一样：反相块画在普通块「上面」，不会把普通块抹掉），
   所以 3 = 两个通道都有 —— 这正是「在实心区块里挖洞」所需要的。 */
const CELL_BIT = { 0: 0, 1: 1, 2: 2 }
function cellMatches(v, value) { const b = CELL_BIT[value]; return b === 0 ? v === 0 : (v & b) !== 0 }
function paintCell(i, value) {
  const cur = S.cells[i]
  S.cells[i] = value === 0 ? 0 : (value === 2 ? (cur | 2) : (cur & ~2) | 1)
}

function buildZones() {
  const out = []
  const { gw, gh, cell, cells, imgW, imgH } = S
  if (cells && gw && gh) {
    /* 两个通道各扫一遍：bit0 → 普通区块，bit1 → 反相区块 */
    for (const bit of [1, 2]) {
      for (let y = 0; y < gh; y++) {
        let x = 0
        while (x < gw) {
          if (!(cells[y * gw + x] & bit)) { x++; continue }
          let x2 = x + 1; while (x2 < gw && (cells[y * gw + x2] & bit)) x2++
          const px = x * cell, py = y * cell
          const pw = Math.min(x2 * cell, imgW) - px, ph = Math.min((y + 1) * cell, imgH) - py
          if (pw > 0 && ph > 0) out.push({ x: px, y: py, w: pw, h: ph, subtract: (bit === 2) })
          x = x2
        }
      }
    }
  }
  for (const r of S.rects) out.push({ x: r.x, y: r.y, w: r.w, h: r.h, subtract: !!r.subtract })
  return out
}

function dilate32(src, dst, width, height) {
  const stride = (width + 31) >> 5
  const lastMask = (0xFFFFFFFF >>> ((32 - (width % 32)) % 32)) >>> 0
  for (let y = 0; y < height; y++) {
    const y0 = y > 0 ? y - 1 : 0, y1 = y < height - 1 ? y + 1 : height - 1
    for (let w = 0; w < stride; w++) {
      let v = 0
      for (let row = y0; row <= y1; row++) {
        const idx = row * stride + w
        const mid = src[idx]
        const left = w > 0 ? (src[idx - 1] >>> 31) : 0
        const right = w + 1 < stride ? (src[idx + 1] << 31) : 0
        v |= mid | (mid << 1) | left | (mid >>> 1) | right
      }
      dst[y * stride + w] = (w + 1 === stride) ? ((v & lastMask) >>> 0) : (v >>> 0)
    }
  }
}

function computeMasks(W, H, zones, time, edgePasses, noiseStrength, blockPx) {
  /* 一格 = blockPx 个原图像素（官方写死 8）；blockPx 最小 1，格数受 BW_MAX 封顶 */
  const bp = Math.max(1, Math.min(64, Math.round(blockPx) || 4))
  const bw = Math.max(1, Math.min(Math.floor(W / bp), BW_MAX))
  const bh = Math.max(1, Math.min(Math.floor(H / bp), BW_MAX))
  const ew = bw * 2, eh = bh * 2, n = bw * bh
  /* 边缘环带占前几格：1 格 ≈ 4 个原图像素，官方默认 = 1 格（系数越大环带越细） */
  const ep = Math.max(1, Math.min(6, edgePasses || 1))
  const norm = new Float32Array(n), sub = new Float32Array(n)
  const sx = bw / W, sy = bh / H

  /* 逐区块「覆盖」：普通 = 满值，反相 = 0.1（官方 SubtractBlockBlender 的阈值窗口 [0.09,0.12)）。
     这里是覆盖而不是累加：官方的累加是「一个 blockArea 画一次」，
     而我们的画笔笔迹会被 buildZones 拆成几百条 1 像素高的扫描线矩形。 */
  let zcount = 0
  for (const z of zones) {
    if (z.w <= 0 || z.h <= 0) continue
    let x0 = Math.ceil(z.x * sx - 0.5), x1 = Math.floor((z.x + z.w) * sx - 0.5) + 1
    let y0 = Math.ceil(z.y * sy - 0.5), y1 = Math.floor((z.y + z.h) * sy - 0.5) + 1
    /* 比一个遮罩格还窄的矩形，整个落在两格中心之间 → 一条都覆盖不到，会静默消失。
       画笔栅格细化到 1px 后这几乎是必然发生，按「矩形中心落在哪一格」兜底。 */
    if (x1 <= x0) { x0 = Math.floor((z.x + z.w * 0.5) * sx); x1 = x0 + 1 }
    if (y1 <= y0) { y0 = Math.floor((z.y + z.h * 0.5) * sy); y1 = y0 + 1 }
    if (x0 < 0) x0 = 0; if (y0 < 0) y0 = 0
    if (x1 > bw) x1 = bw; if (y1 > bh) y1 = bh
    const v = z.subtract ? 26 : 255          /* 26/255 ≈ 0.102，落在官方窗口正中 */
    const dst = z.subtract ? sub : norm
    for (let y = y0; y < y1; y++) {
      const row = y * bw
      for (let x = x0; x < x1; x++) dst[row + x] = v
    }
    zcount++
  }
  /* 反相层：官方 SubtractBlockBlender 的阈值窗口 [0.09,0.12) */
  const compose = new Uint8Array(n)
  for (let i = 0; i < n; i++) {
    const r = sub[i] / 255
    compose[i] = Math.abs(norm[i] - ((r >= 0.09 && r < 0.12) ? 255 : 0))
  }
  /* 双向噪声置换（BlockCompose pass 0）。官方振幅系数固定 0.1；
     「外圈噪声强度」放大它 → 每个区块独立地按远处噪声决定归属，
     外轮廓就从一条锯齿线碎成一颗颗小像素块。0 = 完全不抖（干净方块）。 */
  const nstr = Math.max(0, noiseStrength === undefined ? 1 : noiseStrength)
  const amp = 0.1 * nstr
  const d = 0.70703125, dt = d * (time / 20 * 2.59)
  const wxA = new Int32Array(bw), wxB = new Int32Array(bw)
  for (let x = 0; x < bw; x++) {
    const u = (x + 0.5) / bw
    wxA[x] = noiseIndex(dt + u * 2.13, NOISE_W)
    wxB[x] = noiseIndex(-dt + u * 2.13, NOISE_W)
  }
  const wyRow = new Int32Array(bh)
  for (let y = 0; y < bh; y++) wyRow[y] = noiseIndex(dt + ((y + 0.5) / bh) * 1.02, NOISE_H) * NOISE_W

  const fm = new Uint8Array(n)
  for (let y = 0; y < bh; y++) {
    const row = wyRow[y]
    for (let x = 0; x < bw; x++) {
      const a = CENTERED[noiseR[row + wxA[x]]]
      const b = CENTERED[noiseR[row + wxB[x]]]
      const u = (d * a + b * -d) * amp + (x + 0.5) / bw
      const v = (d * a + b * d) * amp + (y + 0.5) / bh
      let sxi = Math.floor(u * bw); if (sxi < 0) sxi = 0; else if (sxi > bw - 1) sxi = bw - 1
      let syi = Math.floor(v * bh); if (syi < 0) syi = 0; else if (syi > bh - 1) syi = bh - 1
      fm[y * bw + x] = compose[syi * bw + sxi]
    }
  }
  /* 2 倍最近邻上采样 → uMasks RGBA = (合成, Edge, Glow, 禁用合成=0) */
  const rgba = new Uint8Array(ew * eh * 4)
  const stride = (ew + 31) >> 5
  const active = new Uint32Array(stride * eh)
  for (let y = 0; y < bh; y++) {
    for (let x = 0; x < bw; x++) {
      const m = fm[y * bw + x]
      if (!m) continue
      const px = x * 2, py = y * 2, o = (py * ew + px) * 4, o2 = o + ew * 4
      rgba[o] = m; rgba[o + 4] = m; rgba[o2] = m; rgba[o2 + 4] = m
      const wi = px >> 5, sh = px & 31, bits = (3 << sh) >>> 0
      active[py * stride + wi] = (active[py * stride + wi] | bits) >>> 0
      active[(py + 1) * stride + wi] = (active[(py + 1) * stride + wi] | bits) >>> 0
    }
  }
  /* Edge / Glow：九宫格膨胀 + 环带提取 */
  let ping = active, pong = new Uint32Array(active.length)
  for (let pass = 0; pass < 6; pass++) {
    const w = GLOW_W[pass]; if (w < 0.01) break
    dilate32(ping, pong, ew, eh)
    for (let y = 0; y < eh; y++) {
      const base = y * stride
      for (let wi = 0; wi < stride; wi++) {
        let ring = ((pong[base + wi] & ~ping[base + wi]) >>> 0)
        while (ring !== 0) {
          const low = (ring & -ring) >>> 0
          const bit = 31 - Math.clz32(low)
          const x = wi * 32 + bit
          if (x < ew) {
            const dst = (y * ew + x) * 4
            if (pass < ep) rgba[dst + 1] = 255
            rgba[dst + 2] = Math.round(w * 255)
          }
          ring = ((ring & (ring - 1)) >>> 0)
        }
      }
    }
    const t = ping; ping = pong; pong = t
  }
  return { rgba: rgba, ew: ew, eh: eh, count: zcount }
}

function uploadMask(m) {
  maskEw = m.ew; maskEh = m.eh
  gl.bindTexture(gl.TEXTURE_2D, texMask)
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, m.ew, m.eh, 0, gl.RGBA, gl.UNSIGNED_BYTE, m.rgba)
}

/* ------------------------------------------------------------------ */
/* 渲染                                                                */
/* ------------------------------------------------------------------ */
function previewDims() {
  const W = S.imgW, H = S.imgH
  const maxDim = 1920, maxArea = 1920 * 1080
  const s = Math.min(1, maxDim / Math.max(W, H), Math.sqrt(maxArea / (W * H)))
  return [Math.max(8, Math.round(W * s)), Math.max(8, Math.round(H * s))]
}
/* 遮罩网格固定绑定到「原图分辨率」，与预览/导出的渲染分辨率无关，
   这样预览与导出得到完全相同的区块粒度（官方是「屏幕 / 8」，这里以原图为准）。
   一格 = 最小像素点大小，由 S.blockPx 控制（默认 4，官方 8）。 */
const MASK_MAX = 4096
/* 遮罩网格上限：一格最小 1px 时，4096 宽的图会算出 4096×2304 的格 → 纹理 8192×4608，
   内存与每帧开销都不可接受，所以把每边的格数截到 BW_MAX（纹理边长 2×BW_MAX）。 */
const BW_MAX = 1024
function maskDims() {
  return [Math.max(16, Math.min(S.imgW, MASK_MAX)), Math.max(16, Math.min(S.imgH, MASK_MAX))]
}
function blockDiv() { return Math.max(1, Math.min(64, Math.round(S.blockPx) || 4)) }
/* 真实生效的格数与一格多少原图像素（被 MASK_MAX / BW_MAX 截断时会和滑块值不同，如实显示） */
function maskGrid() {
  const W = maskDims()[0], H = maskDims()[1], bp = blockDiv()
  const bw = Math.max(1, Math.min(Math.floor(W / bp), BW_MAX))
  const bh = Math.max(1, Math.min(Math.floor(H / bp), BW_MAX))
  return { W: W, H: H, bw: bw, bh: bh }
}
function maskBlockPx() { const g = maskGrid(); return g.W / g.bw }
/* 边缘像素强度 1..6（越大越细）：反向映射成「环带占几格」 */
function edgePassesOf() { return 7 - clamp(Math.round(S.edgeStrength) || 6, 1, 6) }
/* 边缘环带是按 2× 过采样的遮罩纹理算的，所以 1 格环带 = 半格像素 */
function edgeTexelPx() { return maskBlockPx() / 2 }
function fmtPx(px) { return Math.abs(px - Math.round(px)) < 0.05 ? String(Math.round(px)) : px.toFixed(1) }
/* 只显示实际换算出的像素大小 */
function blockInfo() { return fmtPx(maskBlockPx()) + ' px' }
function edgeInfo() {
  const ep = edgePassesOf(), px = ep * edgeTexelPx()
  return S.edgeStrength + ' · ' + fmtPx(px) + ' px'
}
/* 始终显示换算出的像素大小：还没导入图片时按最小网格兜底，滑动时能实时看到读数 */
const blockInfoText = computed(() => blockInfo())
const edgeInfoText = computed(() => edgeInfo())

function bind(unit, tex, name) {
