  gl.bindTexture(gl.TEXTURE_2D, tex)
  gl.uniform1i(uB(name), unit)
}

function renderInto(W, H) {
  const zones = buildZones()
  const md = maskDims()
  const key = md[0] + 'x' + md[1] + '|' + S.time.toFixed(4) + '|' + S.rev + '|' + S.edgeStrength + '|' + S.noiseStrength + '|' + S.blockPx
  let zoneCount = zones.length
  if (key !== maskKey) {
    const tm = performance.now()
    const m = computeMasks(md[0], md[1], zones, S.time, edgePassesOf(), S.noiseStrength, blockDiv())
    uploadMask(m)
    maskMs = performance.now() - tm
    maskKey = key; zoneCount = m.count
  }
  S.zoneCount = zoneCount

  gl.viewport(0, 0, W, H)
  gl.disable(gl.BLEND)
  gl.clearColor(0, 0, 0, 1)
  gl.clear(gl.COLOR_BUFFER_BIT)

  /* 场景底图 */
  gl.useProgram(progBlit)
  gl.activeTexture(gl.TEXTURE0)
  gl.bindTexture(gl.TEXTURE_2D, texImage)
  gl.uniform1i(uBlit('uTex'), 0)
  gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)

  /* 效果层：One / OneMinusSrcAlpha（官方激活层混合） */
