  gl.enable(gl.BLEND)
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA)

  for (const [k, v] of Object.entries(S.params)) gl.uniform1f(uB(k), v)
  for (const [k, v] of Object.entries(BASE_COLORS)) gl.uniform4f(uB(k), v[0], v[1], v[2], v[3])
  gl.uniform3f(uB('_SparkTint'), SPARK_TINT[0], SPARK_TINT[1], SPARK_TINT[2])
  gl.uniform3f(uB('uDisabledSparkTint'), 0.31132078, 0.077830195, 0.077830195)
  gl.uniform4f(uB('uUnityTime'), S.time / 20, S.time, S.time * 2, S.time * 3)
  gl.uniform4f(uB('_ScreenParams'), W, H, 1 + 1 / W, 1 + 1 / H)
  gl.uniform4f(uB('_EffectRT_TexelSize'), 1 / maskEw, 1 / maskEh, maskEw, maskEh)
  gl.uniform1i(uB('_TouchPosCount'), 0)
  gl.uniform1i(uB('uLayer'), 3)
  gl.uniform1f(uB('uClipHalfWidth'), 1.0)   /* 关闭官方 Ready 用的左右裁切 */

  bind(0, texDisplace, 'uDisplaceTex')
  bind(1, texSpark, 'uSparkTex')
  bind(2, texMask, 'uMasks')
  bind(3, texImage, 'uScene')
  bind(4, texAux, 'uAuxMasks')
  bind(5, texNoise, 'uNoiseTex')
  gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
  gl.disable(gl.BLEND)
}

let _renderT0 = 0
function renderNow() {
  if (!S.img || !gl) return
  _renderT0 = performance.now()
  const dim = previewDims()
  if (glCanvas.width !== dim[0] || glCanvas.height !== dim[1]) {
    glCanvas.width = dim[0]; glCanvas.height = dim[1]
  }
  renderInto(dim[0], dim[1])
  frameMs = performance.now() - _renderT0
  S.perf = (frameMs || 0).toFixed(1) + ' ms  ·  遮罩 ' + (maskMs || 0).toFixed(1) + ' ms'
}

function requestRender() { dirty = true }

/* ------------------------------------------------------------------ */
/* 覆盖层（拖拽预览 / 光标）                                             */
/* ------------------------------------------------------------------ */
function normRect(a, b) { return { x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(a.x - b.x), h: Math.abs(a.y - b.y) } }

function drawOverlay() {
  if (!octx) return
  const W = overlay.width, H = overlay.height
  octx.clearRect(0, 0, W, H)
  if (!S.img) return
  const sx = W / S.imgW, sy = H / S.imgH
  const d = S.drag
  if (d && d.type === 'rect') {
    const r = normRect(d.a, d.b)
    octx.setLineDash([5, 4]); octx.lineWidth = 1.5; octx.strokeStyle = '#fff'
    octx.strokeRect(r.x * sx, r.y * sy, r.w * sx, r.h * sy); octx.setLineDash([])
  }
  if (d && d.type === 'line') {
    const r = Math.max(S.brush / 2, S.cell * 0.5)
    octx.save()
    octx.globalAlpha = .55
    octx.lineCap = 'round'; octx.lineWidth = Math.max(1, r * 2 * sx)
    octx.strokeStyle = d.value === 2 ? '#ffb454' : '#ff5a5f'
    octx.beginPath(); octx.moveTo(d.a.x * sx, d.a.y * sy); octx.lineTo(d.b.x * sx, d.b.y * sy); octx.stroke()
    octx.globalAlpha = 1; octx.lineWidth = 1.5; octx.setLineDash([5, 4]); octx.strokeStyle = '#fff'
    octx.beginPath(); octx.moveTo(d.a.x * sx, d.a.y * sy); octx.lineTo(d.b.x * sx, d.b.y * sy); octx.stroke()
    octx.setLineDash([])
    octx.restore()
  }
  const hv = S.hover
  const wantTip = S.tool === 'brush' || S.tool === 'eraser' || S.tool === 'line'
  if (hv && wantTip && !(d && d.type === 'move') && !(d && d.type === 'line')) {
    const r = Math.max(2, (S.brush / 2) * sx)
    octx.lineWidth = 1.5
    octx.strokeStyle = S.tool === 'eraser' ? '#41d18a' : (S.subtract ? '#ffb454' : '#ff5a5f')
    octx.beginPath()
    if (S.square) octx.rect(hv.x * sx - r, hv.y * sy - r, r * 2, r * 2)
    else octx.arc(hv.x * sx, hv.y * sy, r, 0, Math.PI * 2)
