  }
  if (hv && S.tool === 'fill' && !d) {
    octx.lineWidth = 1.5; octx.strokeStyle = S.subtract ? '#ffb454' : '#ff5a5f'
    octx.beginPath()
    octx.moveTo(hv.x * sx - 7, hv.y * sy); octx.lineTo(hv.x * sx + 7, hv.y * sy)
