}

/* ------------------------------------------------------------------ */
/* 编辑                                                                */
/* ------------------------------------------------------------------ */
function snapshot() { return { cells: S.cells.slice(), rects: S.rects.map(r => ({ x: r.x, y: r.y, w: r.w, h: r.h, subtract: r.subtract })) } }
function pushUndo() { S.history.push(snapshot()); if (S.history.length > 80) S.history.shift(); S.future.length = 0 }
