function undo() { if (!S.history.length) return; S.future.push(snapshot()); restore(S.history.pop()); requestRender(); drawOverlay() }
function redo() { if (!S.future.length) return; S.history.push(snapshot()); restore(S.future.pop()); requestRender(); drawOverlay() }

function stampCircle(px, py, r, value) {
  const c = S.cell, gw = S.gw, gh = S.gh, cells = S.cells
  const sq = S.square
  const cx0 = Math.floor((px - r) / c), cx1 = Math.floor((px + r) / c)
  const cy0 = Math.floor((py - r) / c), cy1 = Math.floor((py + r) / c)
  for (let cy = cy0; cy <= cy1; cy++) {
    if (cy < 0 || cy >= gh) continue
    const row = cy * gw
    for (let cx = cx0; cx <= cx1; cx++) {
      if (cx < 0 || cx >= gw) continue
      const dx = (cx + 0.5) * c - px, dy = (cy + 0.5) * c - py
      if (sq ? (Math.abs(dx) > r || Math.abs(dy) > r) : (dx * dx + dy * dy > r * r)) continue
      paintCell(row + cx, value)
    }
  }
}
/* 油漆桶：从落点出发扩散，把连通区改成 value。
   「同一个区」按目标通道判定：涂普通看 bit0、涂反相看 bit1、橡皮看整个格值。
   注意：涂完的格子仍然属于该通道，所以必须用独立的 seen 位图防重入，
   不能靠「值被改掉」来终止。 */
function bucketFill(p, value) {
  const gw = S.gw, gh = S.gh, cells = S.cells
  const cx = Math.floor(p.x / S.cell), cy = Math.floor(p.y / S.cell)
  if (cx < 0 || cy < 0 || cx >= gw || cy >= gh) return 0
  const key = (v) => value === 0 ? v : (value === 2 ? ((v >> 1) & 1) : (v & 1))
  const k0 = key(cells[cy * gw + cx])
  if (value === 0 ? k0 === 0 : k0 === 1) return 0   /* 落点本来就在目标区里 */
  const seen = new Uint8Array(gw * gh)
  const stack = [cy * gw + cx]
  seen[cy * gw + cx] = 1
  let filled = 0
  while (stack.length) {
    const i = stack.pop()
    paintCell(i, value); filled++
    const x = i % gw, y = (i - x) / gw
    if (x > 0 && !seen[i - 1] && key(cells[i - 1]) === k0) { seen[i - 1] = 1; stack.push(i - 1) }
    if (x < gw - 1 && !seen[i + 1] && key(cells[i + 1]) === k0) { seen[i + 1] = 1; stack.push(i + 1) }
    if (y > 0 && !seen[i - gw] && key(cells[i - gw]) === k0) { seen[i - gw] = 1; stack.push(i - gw) }
    if (y < gh - 1 && !seen[i + gw] && key(cells[i + gw]) === k0) { seen[i + gw] = 1; stack.push(i + gw) }
  }
  return filled
}
function strokeTo(a, b, value) {
  const r = Math.max(S.brush / 2, S.cell * 0.5)
  const dx = b.x - a.x, dy = b.y - a.y
  const dist = Math.hypot(dx, dy)
  const steps = Math.max(1, Math.ceil(dist / Math.max(1, r * 0.5)))
  for (let i = 0; i <= steps; i++) stampCircle(a.x + dx * i / steps, a.y + dy * i / steps, r, value)
}
function eraseRectsAt(p) {
  const n = S.rects.length
  S.rects = S.rects.filter(r => !(p.x >= r.x && p.x <= r.x + r.w && p.y >= r.y && p.y <= r.y + r.h))
