/* ------------------------------------------------------------------ */
/* 布局                                                                */
/* ------------------------------------------------------------------ */
function layout() {
  if (!S.img || !stageEl || !frameEl) return
  const cs = getComputedStyle(stageEl)
  const padX = parseFloat(cs.paddingLeft) || 0, padY = parseFloat(cs.paddingTop) || 0
  const availW = stageEl.clientWidth - padX * 2, availH = stageEl.clientHeight - padY * 2
  const s = Math.min(availW / S.imgW, availH / S.imgH)
  const w = Math.max(64, Math.floor(S.imgW * s)), h = Math.max(64, Math.floor(S.imgH * s))
  frameEl.style.width = w + 'px'; frameEl.style.height = h + 'px'
  const dpr = Math.min(window.devicePixelRatio || 1, 2)
  const ow = Math.max(1, Math.floor(w * dpr)), oh = Math.max(1, Math.floor(h * dpr))
  if (overlay.width !== ow || overlay.height !== oh) { overlay.width = ow; overlay.height = oh }
  overlay.style.width = w + 'px'; overlay.style.height = h + 'px'
  drawOverlay()
  requestRender()
}

/* ------------------------------------------------------------------ */
/* 图片导入 / 导出                                                      */
/* ------------------------------------------------------------------ */
function loadImg(src) {
  return new Promise((res, rej) => {
    const i = new Image()
    i.onload = () => res(i)
    i.onerror = () => rej(new Error('图片载入失败'))
    i.src = src
  })
}
function setImage(img, name) {
  S.img = markRaw(img)
  S.imgW = img.naturalWidth; S.imgH = img.naturalHeight; S.name = name || 'image'
  /* 画笔栅格：默认约 480 行，且总格数不超过 ~140 万（保证 1px 方块也有意义，又不至于卡住） */
  let c = Math.max(1, Math.round(Math.min(S.imgW, S.imgH) / 480))
  while (c < 64 && Math.ceil(S.imgW / c) * Math.ceil(S.imgH / c) > 1400000) c++
  S.cell = c
  S.gw = Math.ceil(S.imgW / S.cell)
  S.gh = Math.ceil(S.imgH / S.cell)
  S.cells = markRaw(new Uint8Array(S.gw * S.gh))
  S.rects = []; S.history = []; S.future = []; S.sel = null; S.drag = null; S.hover = null
  S.rev++; maskKey = ''
  if (texImage) gl.deleteTexture(texImage)
  texImage = texFromImage(gl, img, gl.CLAMP_TO_EDGE, gl.LINEAR)
  layout(); drawOverlay(); requestRender()
}
async function importFile(file) {
  if (!file || !/^image\//.test(file.type)) { showErr('请选择图片文件'); return }
  const url = URL.createObjectURL(file)
  try { const img = await loadImg(url); setImage(img, file.name) }
  catch (err) { showErr(String(err.message || err)) }
  finally { setTimeout(() => URL.revokeObjectURL(url), 1000) }
}
function exportPNG() {
  if (!S.img) return
  const maxDim = 4096
  const s = Math.min(1, maxDim / Math.max(S.imgW, S.imgH))
  const ew = Math.max(8, Math.round(S.imgW * s)), eh = Math.max(8, Math.round(S.imgH * s))
  const oldW = glCanvas.width, oldH = glCanvas.height
  glCanvas.width = ew; glCanvas.height = eh; maskKey = ''
  try { renderInto(ew, eh) }
  catch (err) { showErr('渲染失败: ' + err.message); glCanvas.width = oldW; glCanvas.height = oldH; return }
  const restoreCanvas = () => { glCanvas.width = oldW; glCanvas.height = oldH; maskKey = ''; requestRender() }
  if (glCanvas.toBlob) {
    glCanvas.toBlob(blob => {
      restoreCanvas()
      if (!blob) { showErr('导出失败'); return }
      const a = document.createElement('a')
      a.href = URL.createObjectURL(blob)
      a.download = (S.name.replace(/\.[^.]+$/, '') || 'blockarea') + '-blockarea.png'
      document.body.appendChild(a); a.click(); a.remove()
      setTimeout(() => URL.revokeObjectURL(a.href), 5000)
    }, 'image/png')
  } else {
    restoreCanvas()
    const a = document.createElement('a')
    a.href = glCanvas.toDataURL('image/png')
    a.download = (S.name.replace(/\.[^.]+$/, '') || 'blockarea') + '-blockarea.png'
    a.click()
  }
}

/* ------------------------------------------------------------------ */
/* UI 交互                                                             */
/* ------------------------------------------------------------------ */
function setTool(t) {
  S.tool = t
  drawOverlay()
}
function pickFile() { if (fileRef.value) fileRef.value.click() }
function onFileChange(e) {
  const f = e.target.files && e.target.files[0]
  if (f) importFile(f)
  e.target.value = ''
}
function onDrop(e) {
  dragging.value = false
  const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]
  if (f) importFile(f)
}
function onBrushInput(e) {
  S.brush = parseInt(e.target.value, 10)
  if (S.tool !== 'brush' && S.tool !== 'eraser') setTool('brush')
  requestRender(); drawOverlay()
}
function setBrushTip(sq) { S.square = sq; drawOverlay() }
function onInvertChange(e) { S.subtract = e.target.checked; drawOverlay() }
function onTimeInput(e) { S.time = parseFloat(e.target.value); maskKey = ''; requestRender() }
function togglePlay() { S.playing = !S.playing }
function onBlockPxInput(e) {
  S.blockPx = parseInt(e.target.value, 10) || 4
  maskKey = ''; requestRender()   /* 环带像素数跟着方块粒度走（读数由 computed 刷新） */
}
function onEdgeInput(e) { S.edgeStrength = parseInt(e.target.value, 10) || 6; maskKey = ''; requestRender() }
function onNoiseInput(e) { S.noiseStrength = parseFloat(e.target.value); maskKey = ''; requestRender() }
