function onUndo() { undo() }
function onRedo() { redo() }
function onClear() {
  if (!S.img) return
  pushUndo()
  S.cells.fill(0); S.rects = []; S.sel = null
  S.rev++; maskKey = ''; requestRender(); drawOverlay()
}

function onKeyDown(e) {
  if (e.target && /input|textarea/i.test(e.target.tagName)) return
  if (!(e.ctrlKey || e.metaKey)) return
  const k = e.key.toLowerCase()
  if (k === 'z') { e.preventDefault(); undo() }
  else if (k === 'y') { e.preventDefault(); redo() }
}
function onResize() { layout() }

/* ------------------------------------------------------------------ */
/* 启动 / 卸载                                                         */
/* ------------------------------------------------------------------ */
function loop(ts) {
  if (disposed) return
  rafId = requestAnimationFrame(loop)
  if (S.playing) {
    S.time = (S.time + (lastT ? (ts - lastT) / 1000 : 0)) % 60
    maskKey = ''; dirty = true
  }
  lastT = ts
  if (dirty && S.img) {
    dirty = false
    _renderT0 = performance.now()
    renderNow()
  }
}

onMounted(async () => {
  stageEl = stageRef.value
  frameEl = frameRef.value
  overlay = overlayRef.value
  glCanvas = viewRef.value
  octx = overlay.getContext('2d')

  frameEl.addEventListener('pointerdown', onDown)
  frameEl.addEventListener('pointermove', onMove)
  frameEl.addEventListener('pointerup', onUp)
  frameEl.addEventListener('pointercancel', onUp)
  frameEl.addEventListener('pointerleave', onPointerLeave)
  window.addEventListener('resize', onResize)
  window.addEventListener('keydown', onKeyDown)

  try {
    const imgs = await Promise.all([loadImg(TEX_DISPLACE_URL), loadImg(TEX_SPARK_URL), loadImg(TEX_NOISE_URL)])
    imgDisplace = imgs[0]; imgSpark = imgs[1]; imgNoise = imgs[2]
    NOISE_W = imgDisplace.naturalWidth; NOISE_H = imgDisplace.naturalHeight
    const c = document.createElement('canvas'); c.width = NOISE_W; c.height = NOISE_H
    const cx = c.getContext('2d', { willReadFrequently: true })
    cx.drawImage(imgDisplace, 0, 0)
    const data = cx.getImageData(0, 0, NOISE_W, NOISE_H).data
    noiseR = new Uint8Array(NOISE_W * NOISE_H)
    for (let i = 0; i < noiseR.length; i++) noiseR[i] = data[i * 4]

    initGL()
    setTool('brush')
    rafId = requestAnimationFrame(loop)
  } catch (err) {
    showErr(String(err && err.stack || err))
  }
})

function onPointerLeave() {
  S.hover = null
  drawOverlay()
}

onBeforeUnmount(() => {
  disposed = true
  cancelAnimationFrame(rafId)
  clearTimeout(errTimer)
  window.removeEventListener('resize', onResize)
  window.removeEventListener('keydown', onKeyDown)
  if (frameEl) {
    frameEl.removeEventListener('pointerdown', onDown)
    frameEl.removeEventListener('pointermove', onMove)
    frameEl.removeEventListener('pointerup', onUp)
    frameEl.removeEventListener('pointercancel', onUp)
    frameEl.removeEventListener('pointerleave', onPointerLeave)
  }
  if (gl) {
    const lose = gl.getExtension('WEBGL_lose_context')
    if (lose) lose.loseContext()
  }
  gl = null
})
</script>

